  "composition_summary": "Preserved the volatile tail unchanged (single user request, no justified repair). Drafted one pure-logic class-22 component pc-transfer-02 with name/description/content only, per the supported offline-design sink. The body is executable Python at module scope: it reads raw inputs via inputs.get() so missing/empty/any-JSON values are inspected rather than raising, validates that quota is an exact integer in -2..7 inclusive (rejecting bool/float/strings), and assigns result to {accepted, quota} on every branch without exceptions or coercion. No imports, I/O, host calls, Markdown, or guessed UUIDs. This is an unapproved draft; typed-input transport and runner support remain prerequisites, and no observed tests/submission/activation are claimed.",
  "adjusted_volatile_messages": [["user", "Prepare the requested reusable draft without executing any operation."]],
  "settings_adjustments": [],
  "proposed_components": [
    {
      "class_code": 22,
      "payload": {
        "name": "pc-transfer-02",
        "description": "Pure-logic guard: accepts a raw quota value only when it is an exact integer in -2..7 inclusive (booleans and floats are rejected). Returns {accepted, quota} where quota is the original value when accepted, else null. No imports, I/O, host calls or exceptions.",
        "content": "def classify_quota(quota):\n    if type(quota) is bool or not type(quota) is int or not -2 <= quota <= 7:\n        result = {'accepted': False, 'quota': None}\n    else:\n        result = {'accepted': True, 'quota': quota}\nresult = classify_quota(inputs.get('quota'))"
      }
    }
  ]
}
